// A dependency-free static server for the workbench: the repository root is the site
// (index.html is generated by `npm run build`; /node_modules/* is the app's own
// vendor directory, which is what the import map points at).
//
//   node scripts/serve.mjs [port]
//   node scripts/serve.mjs [port] --dir dist --prefix /workbench/
//       serves a deployable build (npm run build:pages) the way GitHub Pages does: the whole directory is public, under a subpath
import { createServer } from "node:http";
import { readFile, stat } from "node:fs/promises";
import { extname, join, normalize, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

const argv = process.argv.slice(2);
const option = (name) => { const i = argv.indexOf(name); return i >= 0 ? argv[i + 1] : undefined; };
const positional = argv.filter((a, i) => !a.startsWith("--") && !argv[i - 1]?.startsWith("--"));
const repo = resolve(fileURLToPath(new URL("..", import.meta.url)));
const dir = option("--dir");
const root = dir ? resolve(dir) : repo;
const prefix = option("--prefix") ? option("--prefix").replace(/^\/?/, "/").replace(/\/?$/, "/") : "/";
const port = Number(positional[0] ?? process.env.PORT ?? 4399);
const TYPES = {
  ".html": "text/html; charset=utf-8",
  ".mjs": "text/javascript; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".svg": "image/svg+xml",
};
// Only these top-level paths are public; everything else (scripts, tests, .git) is not.
const PUBLIC = new Set(["index.html", "app", "components", "styles", "node_modules", "favicon.svg"]);

createServer(async (request, response) => {
  try {
    const url = new URL(request.url, "http://localhost");
    if (prefix !== "/" && url.pathname === prefix.slice(0, -1)) { response.writeHead(301, { location: prefix }); response.end(); return; }
    if (!url.pathname.startsWith(prefix)) throw Object.assign(new Error("outside the prefix"), { code: "ENOENT" });
    const rel = normalize(`/${decodeURIComponent(url.pathname.slice(prefix.length))}`).replace(/^[/\\]+/, "");
    const top = rel.split(sep)[0];
    if (!dir && rel !== "" && !PUBLIC.has(top)) throw Object.assign(new Error("not public"), { code: "ENOENT" });
    let path = join(root, rel);
    if (path !== root && !path.startsWith(root + sep)) throw Object.assign(new Error("outside root"), { code: "ENOENT" });
    let info = await stat(path);
    if (info.isDirectory()) {
      path = join(path, "index.html");
      info = await stat(path);
    }
    const body = await readFile(path);
    response.writeHead(200, { "content-type": TYPES[extname(path)] ?? "application/octet-stream", "cache-control": "no-store" });
    response.end(body);
  } catch (error) {
    response.writeHead(error.code === "ENOENT" || error.code === "ENOTDIR" ? 404 : 500, { "content-type": "text/plain" });
    response.end(error.code === "ENOENT" || error.code === "ENOTDIR" ? "Not found" : String(error));
  }
}).listen(port, "127.0.0.1", () => console.log(`workbench: http://127.0.0.1:${port}${prefix}`));
